parts.spider( config := config_ref.spider );
parts.m1Cell( config := config_ref.m1Cell );
parts.spare( config := config_ref.spare );
stat.health := F_HealthStatus(
    superState := TRUE,
    isGood := ((NOT(parts.basePlate.stat.health = HealthStatus.bad)) OR (parts.basePlate.stat.enabled = EnabledStatus.disabled)) AND (((NOT(parts.electronics.stat.health = HealthStatus.bad)) OR (parts.electronics.stat.enabled = EnabledStatus.disabled)) AND (((NOT(parts.ambient.stat.health = HealthStatus.bad)) OR (parts.ambient.stat.enabled = EnabledStatus.disabled)) AND (((NOT(parts.fork.stat.health = HealthStatus.bad)) OR (parts.fork.stat.enabled = EnabledStatus.disabled)) AND (((NOT(parts.truss.stat.health = HealthStatus.bad)) OR (parts.truss.stat.enabled = EnabledStatus.disabled)) AND (((NOT(parts.spider.stat.health = HealthStatus.bad)) OR (parts.spider.stat.enabled = EnabledStatus.disabled)) AND (((NOT(parts.m1Cell.stat.health = HealthStatus.bad)) OR (parts.m1Cell.stat.enabled = EnabledStatus.disabled)) AND ((NOT(parts.spare.stat.health = HealthStatus.bad)) OR (parts.spare.stat.enabled = EnabledStatus.disabled)))))))),
    hasWarning := (parts.basePlate.stat.health = HealthStatus.warning) OR ((parts.electronics.stat.health = HealthStatus.warning) OR ((parts.ambient.stat.health = HealthStatus.warning) OR ((parts.fork.stat.health = HealthStatus.warning) OR ((parts.truss.stat.health = HealthStatus.warning) OR ((parts.spider.stat.health = HealthStatus.warning) OR ((parts.m1Cell.stat.health = HealthStatus.warning) OR (parts.spare.stat.health = HealthStatus.warning))))))));

